class Balanced(MovingCameraScene):
    def construct(self):
        yorange = (YELLOW + ORANGE) / 2
        cmap = plt.get_cmap("plasma")

        x_min, x_max = -4, 4
        y_min, y_max = -4, 4
        resolution = 1600
        plane_size = 6.0

        plane = ComplexPlane(x_range=[x_min, x_max, 1], y_range=[y_min, y_max, 1],
                             x_length=plane_size, y_length=plane_size,
                             axis_config={"color": BLUE, "stroke_width": 2.5, "stroke_opacity": 0.35},
                             background_line_style={"stroke_color": BLUE, "stroke_width": 2.5, "stroke_opacity": 0.35},
                             faded_line_style={"stroke_color": BLUE, "stroke_width": 1.0, "stroke_opacity": 0.2},
                             faded_line_ratio=5)
        border = SurroundingRectangle(plane, color=BLUE, buff=0, stroke_width=3).set_z_index(5)

        layers = getGrid().set_color(BLUE)

        box_source_coords = getCoords()
        sources = VGroup([Dot(color=BLUE_B, radius=DEFAULT_SMALL_DOT_RADIUS).move_to(plane.c2p(coord[0], coord[1]))
                          for coords in box_source_coords for coord in coords]).set_z_index(10)

        def get_multipole(p, center, source_coords):
            a_coeff = [len(source_coords)]
            for k in range(1, 21):
                res = 0
                for x, y in source_coords:
                    z_i = x + 1j * y
                    res += (z_i - center) ** k
                a_coeff.append(-1 / k * res)

            def evaluate(z):
                res = a_coeff[0] * np.log(z - center)
                for k in range(1, p + 1):
                    res += a_coeff[k] * (z - center) ** -k
                return np.real(res)

            return evaluate

        def get_local(p, center, source_coords):
            a_coeff = []
            sum = 0
            for x, y in source_coords:
                z_i = x + 1j * y
                sum += np.log(-(z_i - center))
            a_coeff.append(sum)
            for k in range(1, 21):
                res = 0
                for x, y in source_coords:
                    z_i = x + 1j * y
                    res += (z_i - center) ** -k
                a_coeff.append(-1 / k * res)

            def evaluate(z):
                res = np.full_like(z, fill_value=a_coeff[0])
                for k in range(1, p + 1):
                    res += a_coeff[k] * (z - center) ** k
                return np.real(res)

            return evaluate

        def get_mheatmap(func, center, radius):
            x = np.linspace(np.real(center) - radius, np.real(center) + radius, int(resolution * radius / 4))
            y = np.linspace(np.imag(center) + radius, np.imag(center) - radius, int(resolution * radius / 4))
            X, Y = np.meshgrid(x, y)
            Z = X + 1j * Y
            raw_values = func(Z)
            raw_values = np.nan_to_num(raw_values, nan=0.0, posinf=0.0, neginf=0.0)

            val_min, val_max = raw_values.min(), raw_values.max()
            rgba_image = cmap(raw_values / (30 * radius ** 2 * np.log(radius * np.sqrt(2)) ))
            rgba_image[:, :, 3] = 0.75
            rgb_uint8 = (rgba_image * 255).astype(np.uint8)

            res = ImageMobject(rgb_uint8)
            res.width = plane.x_length * radius / 4
            res.height = plane.y_length * radius / 4
            return res.move_to(plane.c2p(np.real(center), np.imag(center)))

        def get_lheatmap(func, center, radius, sz, dist):
            x = np.linspace(np.real(center) - radius, np.real(center) + radius, int(resolution * radius / 4))
            y = np.linspace(np.imag(center) + radius, np.imag(center) - radius, int(resolution * radius / 4))
            X, Y = np.meshgrid(x, y)
            Z = X + 1j * Y
            raw_values = func(Z)
            raw_values = np.nan_to_num(raw_values, nan=0.0, posinf=0.0, neginf=0.0)

            val_min, val_max = raw_values.min(), raw_values.max()
            rgba_image = cmap(raw_values / (1.33 * sz * np.log(dist) ))
            rgba_image[:, :, 3] = 0.75
            rgb_uint8 = (rgba_image * 255).astype(np.uint8)

            res = ImageMobject(rgb_uint8)
            res.width = plane.x_length * radius / 4
            res.height = plane.y_length * radius / 4
            return res.move_to(plane.c2p(np.real(center), np.imag(center)))

        self.wait(0.5)
        self.play(Create(plane), Write(border), run_time=2)
        self.wait()
        self.play(FadeIn(layers[3]), FadeIn(sources))
        self.wait()

        heatmaps = Group()
        level = Group()
        for i in range(64):
            center_coord = plane.p2c(layers[3][i].get_center())
            exp_center = center_coord[0] + 1j * center_coord[1]
            multipole_heatmap = get_mheatmap(get_multipole(10, exp_center, box_source_coords[i]), exp_center, 0.5)
            level.add(multipole_heatmap)
        heatmaps.add(level)

        self.play(AnimationGroup(*[FadeIn(heatmaps[0][i]) for i in range(64)], lag_ratio=0.04),)
        self.wait()

        next_level = Group()
        for i in range(16):
            coords = box_source_coords[i * 4].copy()
            for j in range(i * 4 + 1, i * 4 + 4):
                coords += box_source_coords[j]

            center_coord = plane.p2c(layers[2][i].get_center())
            exp_center = center_coord[0] + 1j * center_coord[1]
            multipole_heatmap = get_mheatmap(get_multipole(15, exp_center, coords), exp_center, 1)
            next_level.add(multipole_heatmap)
        heatmaps.add(next_level)

        self.play(FadeOut(heatmaps[0]), FadeIn(heatmaps[1]))
        self.wait()

        next_level = Group()
        for i in range(4):
            coords = box_source_coords[i * 16].copy()
            for j in range(i * 16 + 1, i * 16 + 16):
                coords += box_source_coords[j]

            center_coord = plane.p2c(layers[1][i].get_center())
            exp_center = center_coord[0] + 1j * center_coord[1]
            multipole_heatmap = get_mheatmap(get_multipole(20, exp_center, coords), exp_center, 2)
            next_level.add(multipole_heatmap)
        heatmaps.add(next_level)

        self.play(FadeOut(heatmaps[1]), FadeIn(heatmaps[2]))
        self.wait()

        coords = box_source_coords[0].copy()
        for i in range(1, 64):
            coords += box_source_coords[i]

        center_coord = plane.p2c(layers[0].get_center())
        exp_center = center_coord[0] + 1j * center_coord[1]
        multipole_heatmap = get_mheatmap(get_multipole(20, exp_center, coords), exp_center, 4)
        heatmaps.add(multipole_heatmap)
        self.play(FadeOut(heatmaps[2]), FadeIn(heatmaps[3]))
        self.wait()

        highlight = layers[0].copy().set_color(yorange).set_z_index(20)
        self.play(FadeIn(highlight))
        self.wait()
        highlight2 = layers[1][0].copy().set_color(yorange).set_z_index(20)
        conv_radius = 0.375 * np.sqrt(2)
        conv_circles = VGroup([DashedVMobject(Circle(radius=conv_radius * 4, color=WHITE, stroke_width=4), num_dashes=40)
            .move_to(layers[1][i]) for i in range(1, 4)]).set_z_index(5)
        self.play(AnimationGroup([
            AnimationGroup([Transform(highlight, highlight2), FadeOut(heatmaps[3]), FadeIn(heatmaps[2][1:])]),
                  FadeIn(conv_circles)], lag_ratio=0.4))
        self.wait()

        highlight2 = layers[2][2].copy().set_color(yorange).set_z_index(20)
        arr = [i for i in range(16)]
        arr.remove(2)
        conv_circles2 = VGroup(
            [DashedVMobject(Circle(radius=conv_radius * 2, color=WHITE, stroke_width=3), num_dashes=25)
            .move_to(layers[2][i]) for i in range(16)]).set_z_index(5)
        self.play(Transform(highlight, highlight2), FadeOut(heatmaps[2][1:]), FadeOut(conv_circles),
                  AnimationGroup(*[FadeIn(heatmaps[1][i]) for i in arr]))
        self.wait()

        neighbors = [0, 1, 3, 4, 7, 8, 12, 13]
        self.play(AnimationGroup(*[FadeOut(heatmaps[1][i]) for i in neighbors]))
        self.wait()

        far = [i for i in arr if i not in neighbors]
        self.play(AnimationGroup(*[FadeIn(conv_circles2[i]) for i in far]))
        self.wait()

        coords = []
        for f in far:
            for i in range(f * 4, (f + 1) * 4):
                coords += box_source_coords[i]
        local = Group(get_lheatmap(get_local(20, -1 + 1j, coords), -1 + 1j, 1, 140, 5))
        self.play(FadeIn(local[0]), AnimationGroup(*[FadeOut(heatmaps[1][i], shift=(plane.c2p(-1, 1) - heatmaps[1][i].get_center())) for i in far]),
                  AnimationGroup(*[FadeOut(layers[3][4 * i : 4 * (i + 1)]) for i in far]),
                  AnimationGroup(*[FadeOut(sources[20 * i : 20 * (i + 1)]) for i in far]),
                  AnimationGroup(*[FadeOut(conv_circles2[i]) for i in far]))
        self.wait()

        temp = Group()
        for i in range(4):
            center_coord = plane.p2c(layers[3][8 + i].get_center())
            center = center_coord[0] + 1j * center_coord[1]
            temp.add(get_lheatmap(get_local(20, center, coords), center, 0.5, 140, 5))
        local.add(temp)
        highlight2 = layers[3][9].copy().set_color(yorange).set_z_index(20)
        self.play(self.camera.frame.animate.move_to(plane.c2p(-1, 1)).scale(2/3),
                  FadeOut(local[0]), FadeIn(local[1][1]), Transform(highlight, highlight2))
        self.wait()

        neighbors.append(2)
        arr = []
        for i in neighbors:
            arr.append(4 * i)
            arr.append(4 * i + 1)
            arr.append(4 * i + 2)
            arr.append(4 * i + 3)
        neighbors = [6, 7, 8, 9, 10, 11, 19, 28, 31]
        far = [i for i in arr if i not in neighbors]

        self.play(AnimationGroup(*[FadeIn(heatmaps[0][i]) for i in far]))
        self.wait()
        for i in far:
            coords += box_source_coords[i]
        local.add(get_lheatmap(get_local(20, -0.5 + 1.5j, coords), -0.5 + 1.5j, 0.5, 275, 4))
        self.play(FadeOut(local[1][1]), FadeIn(local[2]),
                  AnimationGroup(*[FadeOut(heatmaps[0][i], shift=(plane.c2p(-0.5, 1.5) - heatmaps[0][i].get_center())) for i in far]),
                  AnimationGroup(*[FadeOut(layers[3][i]) for i in far]),
                  AnimationGroup(*[FadeOut(sources[5 * i : 5 * (i + 1)]) for i in far]),
                  )
        self.wait()

        rect = Rectangle(height=10, width=20, fill_opacity=1, fill_color=BLACK).set_z_index(20)
        title = Text("Rinse and repeat...").set_z_index(21).move_to(layers[2][2])
        self.play(FadeIn(rect), FadeIn(title))
        self.wait(0.5)

        self.play(FadeOut(rect), FadeOut(title),
                  self.camera.frame.animate.move_to(plane.c2p(1.5, 1.5)).scale(1.2/2))
        self.wait()

        bg = Rectangle(width=2.8, height=2.25, fill_color=BLACK, fill_opacity=0.8, stroke_width=3
                       ).move_to(self.camera.frame.get_center()).shift(RIGHT * 1.25).set_z_index(15)
        working = VGroup(Tex("Calculate forces from", r"neighbors as $\vec F_{\text{Near}}(z)$"),
                         MathTex(r"P'_{LE}(z) = \sum_{k = 1}^p kb_kz^{k - 1}"),
                         MathTex(r"\vec F(z) = \langle-\operatorname{Re}(P'_{LE}(z)), \operatorname{Im}(P'_{LE}(z))\rangle",
                                 r"+ \vec F_{\text{Near}}(z)")
                         )
        working[0][1].next_to(working[0][0], DOWN)
        working[0][1][-2].set_color(BLUE)
        working[1][0][5].set_color(BLUE)
        working[1][0][14:16].set_color(YELLOW)
        working[1][0][16].set_color(BLUE)
        working[2][1].next_to(working[2][0], DOWN).align_to(working[2][0][6], LEFT)
        working[2][0][3].set_color(BLUE)
        working[2][0][16].set_color(BLUE)
        working[2][0][28].set_color(BLUE)
        working[2][1][8].set_color(BLUE)

        working.scale(1/3).arrange(DOWN).move_to(self.camera.frame.get_center()).shift(RIGHT * 1.25).set_z_index(16)
        self.play(FadeIn(bg), Write(working[0]))
        self.wait()
        self.play(Write(working[1:]))
        self.wait()


def get_nonuniform_grid():
    yorange = (YELLOW + ORANGE) / 2
    layers = VGroup(Rectangle(height=6, width=6, stroke_width=3.5))
    layers.add(subdivide(layers[0]))
    layers.add(subdivide(layers[1][0]))
    layers[2].add(*subdivide(layers[1][1]))
    layers[2].add(*subdivide(layers[1][2]))
    next = [3, 4, 5, 7, 8]
    layers.add(subdivide(layers[2][2]))
    for i in next:
        layers[-1].add(*subdivide(layers[2][i]))
    layers.add(subdivide(layers[3][2]))
    next = [16, 17, 19, 20, 23]
    for i in next:
        layers[-1].add(*subdivide(layers[3][i]))
    layers.add(subdivide(layers[4][6]))
    layers[-1].add(*subdivide(layers[4][13]))

    return layers

