        self.play(FadeOut(arrows), FadeOut(multipole_conv), FadeOut(ideal_conv), FadeOut(heatmap),
                  Transform(source_highlight, layers[4][-2].copy().set_color(yorange).set_z_index(5)),
                  Transform(target_highlight, layers[1][-1].copy().set_color(GREEN).set_z_index(5)))
        self.wait()

        source_coords = filter([-2, -2], 2)
