        multipole_conv = Circle(radius=rad * 4, color=GREEN, fill_color=GREEN, fill_opacity=0.2
                                ).set_z_index(10).move_to(layers[1][-1])
        local_conv = Circle(radius=rad / 2,color=BLUE, fill_color=BLUE, fill_opacity=0.4
                            ).move_to(layers[4][-2]).set_z_index(12)
        self.play(FadeIn(heatmap), FadeIn(multipole_conv))
        self.wait()
        self.play(FadeIn(local_conv))
