        l_heatmap = get_lheatmap(get_local(10, 0.75 - 1.75j, source_coords), 0, 4, 4, 2.5)
        ideal_conv = DashedVMobject(Circle(radius=0.75 * 0.75).move_to(layers[4][-2]), num_dashes=25
                                    ).set_z_index(10).set_color(WHITE)
        self.play(FadeOut(heatmap), FadeIn(l_heatmap), FadeOut(multipole_conv), Write(ideal_conv))
